# -*- coding: utf-8 -*-
# Datos de especies de Barcanueva. Formato por fila:
# S(id, nombre, nombreCa, cientifico, biomas, tipo, rol, dieta, depredadores, actividad,
#   estacionCria, camada, reproduccion, conducta, recursos, estado, folklore)
# biomas: U urbano, B bosque, P pradera, M montana, R rio, C costa (el primero = bioma principal)
# actividad: M manana, D dia, T tarde, C crepusculo, N noche
# dieta/depredadores: ids de especies o reservas genericas "g:..."

E = []
def S(id, nom, ca, sci, bio, tipo, rol, dieta, dep, act, est, cam, rep, cond, rec, estado, folk=""):
    E.append(dict(id=id, nombre=nom, nombreCa=ca, cientifico=sci, biomas=list(bio), tipo=tipo, rol=rol,
                  dieta=dieta.split() if dieta else [], depredadores=dep.split() if dep else [],
                  actividad=list(act), cria=dict(estacion=est, camada=cam), reproduccion=rep,
                  conducta=cond, recursos=[r.strip() for r in rec.split(",")] if rec else [],
                  estado=estado, folklore=folk))

A, PL, H, F = "animal", "planta", "hongo", "fantastico"

